// External seal. Hashes the manifest, the result, and every command record.
// A command with an exit file is sealed in full. The command that is still
// running (this seal) has cmd.txt only; its out, err, and exit follow the exit.
// Do not edit this file after it has run.
import { createHash } from 'node:crypto';
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

function fileRec(name) {
  const data = readFileSync(resolve(name));
  return { path: name.replaceAll('\\', '/'), sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length };
}
function commandRec(n) {
  const nn = String(n).padStart(2, '0');
  const cmdText = readFileSync(resolve('work/out/cmd/' + nn + '.cmd.txt'), 'utf8');
  const full = existsSync(resolve('work/out/cmd/' + nn + '.exit'));
  const files = { cmd: fileRec('work/out/cmd/' + nn + '.cmd.txt') };
  let status = null;
  if (full) {
    const exitDoc = JSON.parse(readFileSync(resolve('work/out/cmd/' + nn + '.exit'), 'utf8'));
    status = exitDoc.status;
    files.out = fileRec('work/out/cmd/' + nn + '.out');
    files.err = fileRec('work/out/cmd/' + nn + '.err');
    files.exit = fileRec('work/out/cmd/' + nn + '.exit');
  }
  return { n, requested: (cmdText.match(/^requested: (.*)$/m) || [])[1] || '', status, files };
}
const nums = readdirSync(resolve('work/out/cmd')).filter((name) => /^\d+\.cmd\.txt$/.test(name)).map((name) => Number(name.slice(0, name.indexOf('.')))).sort((a, b) => a - b);
const commands = nums.map(commandRec);
const doc = {
  task: 'T8c',
  sealed: 'External seal of the correction. Commands that already have an exit file include cmd, out, err, and exit. The seal command itself has cmd.txt only until this process exits.',
  manifest: fileRec('work/evidence-manifest.json'),
  result: fileRec('work/result.md'),
  commands,
};
writeFileSync(resolve('work/evidence-supplement.json'), JSON.stringify(doc, null, 2) + '\n');
process.stdout.write(JSON.stringify({ ok: true, commands: commands.length, manifest: doc.manifest.sha256 }) + '\n');
